import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs';import{matchingRule,movementResult}from'../core.js';import{matchingPhotographs}from'../photographs.js';
const read=p=>JSON.parse(fs.readFileSync(new URL('../'+p,import.meta.url))),rules=read('research-updates-20261008.json').filter(r=>['2234.50.00','233.30.41.21.01.001'].includes(r.baseReference)),photos=read('photographs.json').photographs.filter(p=>/^omega-(22345000|23330412101001)-20261030-/.test(p.id));
test('Omega exact mappings keep GMT1128 and no-date8400 distinct',()=>{assert.equal(rules.length,2);for(const[r,c]of [['22345000','1128'],['23330412101001','8400']])assert.equal(movementResult(matchingRule(rules,'Omega',r),c).level,'match');for(const ref of ['25345000','23330412101002','23430412101001','255180','223450'])assert.equal(matchingRule(rules,'Omega',ref),null);assert.equal(movementResult(matchingRule(rules,'Omega','23330412101001'),'8912').level,'caution');});
test('Every rear image showing8400 is suppressed externally including clasp category',()=>{assert.equal(photos.length,5);const all=matchingPhotographs(photos,'Omega','23330412101001');assert.equal(all.length,4);const ext=matchingPhotographs(photos,'Omega','23330412101001',{externalOnly:true});assert.equal(ext.length,1);assert.equal(ext[0].category,'front');assert.ok(all.filter(p=>p.category!=='front').every(p=>p.depictsMovement));assert.equal(matchingPhotographs(photos,'Omega','22345000',{externalOnly:true}).length,1);for(const ref of ['25345000','23430412101001','255180'])assert.equal(matchingPhotographs(photos,'Omega',ref).length,0);});
test('255180 supplier-period question remains active without a canonical equivalence',()=>{const s=read('research-queue-omega-next-batch-20261030-sources.json').records.find(r=>r.reference==='255180');assert.equal(s.decision,'needs_evidence');assert.match(s.conclusion,/do not treat the observation as wrong/);assert.ok(!rules.some(r=>r.baseReference==='255180'));});
